package com.trombokendu.chronos.analytics;import java.util.*;public final class ZScoreRule implements AnomalyRule{private final Map<String,OnlineStats> stats;public ZScoreRule(Map<String,OnlineStats>s){stats=s;}public Optional<String> check(double a,String c,String d){OnlineStats s=stats.get(c);return s!=null&&s.count()>2&&Math.abs(a-s.mean())>3*s.stdDev()?Optional.of("Amount exceeds 3 sigma for "+c):Optional.empty();}}
